  "app.local": "डेटा होम नहि खुजल, तेँ मात्र एही साइट पर एहि ब्राउजर मे सेव अछि। अगिला बेर ई डेटा होम मे चलि जायत।",
  "app.vault": "एहि ब्राउजरक डेटा होम मे सेव अछि, जे Nivesh Sahayak क सभ टूल मे साझा अछि। हमरा सभकेँ किछु नहि पठाओल जाइत अछि।",
  "app.help": "ई कोना काज करैत अछि",
  "app.helpp": "billing., cash-memo. आ credit-note. पर बनल बिल एतय अपने देखाइत अछि। भेटल आ देल पाइ एतय लिखू; ऐप ओकरा बिल सँ जोड़ैत अछि, एडवांस रखैत अछि आ बकाया आ हाथक कैश निकालैत अछि।",
