  "b1.tcsh": "मात्र ओहि बिक्री पर जाहि पर बेचनिहारकेँ इनकम टैक्स वसूलबाक होइत अछि: इनकम टैक्स एक्ट 2025 क सेक्शन 394 (पहिने सेक्शन 206C)। फाइनेंस एक्ट 2026 क बादक रेट: शराब, तेंदू पात, लकड़ी वा वन उपज, स्क्रैप, कोयला, लिग्नाइट वा लौह अयस्क 2%; ₹10 लाखसँ ऊपरक गाड़ी वा नोटिफाइड सामान 1%; विदेश टूर पैकेज 2%; पार्किंग, टोल प्लाज़ा, खान 2%। 1 सँ 5 बला सामान पर TCS नहि जँ खरीदार लिखि कऽ दथि जे सामान निर्माण लेल अछि, व्यापार लेल नहि। बाँकी सामान पर TCS नहि (₹50 लाखबला पुरान नियम समाप्त)।",
