  "b1.v_tcs10": "गाड़ी वा नोटिफाइड सामान पर TCS तखने लगैत अछि जखन एकटा आइटमक दाम ₹10 लाख सँ ऊपर हो (नोटिफिकेशन 36/2025 पर CBDT FAQ, 23 अप्रैल 2025)। एहि बिलक कोनो आइटम एहन नहि अछि। TCS क टिक हटाउ।",
  "b1.c_tcs10g": "GST बिना कोनो आइटम ₹10 लाख सँ ऊपर नहि अछि, मात्र GST जोड़ि ऊपर अछि। एक्ट मे \"वैल्यू\" लिखल अछि आ कोनो सर्कुलर तय नहि केलक जे एहि लिमिट मे GST गानल जाए वा नहि। की एहि बिल पर TCS लेबाक अछि?",
